theory.code:
XML:        <bean id="xmlGreeter" class="com.example.Greeter"/>

Adnotacje:  @Component
            class AnnotationStyleGreeter { ... }

Java Config: @Configuration
             class AppConfig {
                 @Bean
                 Greeter javaConfigStyleGreeter() { return new Greeter(); }
             }

@Component
class AnnotationStyleGreeter {
    String greet(String name) { return "Witaj, " + name + "!"; }
}

@Configuration
@ComponentScan // przeszukuje pakiety w poszukiwaniu @Component
class AppConfig {}
// domyslna nazwa beana: "annotationStyleGreeter" (nazwa klasy z mala litera na poczatku)

class JavaConfigStyleGreeter { // CELOWO bez @Component - symuluje klase z biblioteki zewnetrznej
    String greet(String name) { return "Hello, " + name + "!"; }
}

@Configuration
class AppConfig {
    @Bean
    JavaConfigStyleGreeter javaConfigStyleGreeter() {
        return new JavaConfigStyleGreeter(); // TY decydujesz, JAK obiekt powstaje
    }
}
// domyslna nazwa beana: "javaConfigStyleGreeter" (nazwa METODY)
